import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/api/transfer-export.html","title":"导出来源与迁移归档","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1793083391000,"contributors":[{"name":"之旸 刘","username":"","email":"marufyurisa@outlook.com","commits":1}],"changelog":[{"hash":"a7bc7e5f74740c184e03fa5817e5e4576113490b","time":1793083391000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: integrate release workflows, managed backups and runtime fixes"}]},"filePathRelative":"api/transfer-export.md"}`),u={name:`transfer-export.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[12]||=i(`h1`,{id:`导出来源与迁移归档`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#导出来源与迁移归档`},`#`),e(` 导出来源与迁移归档`)],-1),i(`p`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`返回 API 入口`,-1)]]),_:1}),l[2]||=e(` · `,-1),a(m,{to:`/api/scope-identity.html`},{default:r(()=>[...l[1]||=[e(`范围身份`,-1)]]),_:1})]),l[13]||=n(`<p><code>POST /api/v1/transfer/export</code> 支持三种明确来源，统一生成可重新导入编辑区的迁移归档：</p><table><thead><tr><th>source</th><th>说明</th><th>取数</th></tr></thead><tbody><tr><td><code>editor</code></td><td>编辑区当前内容，可多环境/多渠道、可勾选</td><td>当前有效 scope 的配置与引用资源</td></tr><tr><td><code>active</code></td><td>用户看到的生效快照，单范围整份</td><td><code>expected_snapshot_id</code> 对应的 active 版本</td></tr><tr><td><code>version</code></td><td>指定发布版本，单范围整份</td><td>固定 <code>scope_id + version + snapshot_id</code></td></tr></tbody></table><p>发布来源第一版不做跨 scope 混合版本或快照内裁剪。导入后只进入编辑区，不自动锁版、创建版本或切换 active。</p><h2 id="_1-导出请求" tabindex="-1"><a class="header-anchor" href="#_1-导出请求">#</a> 1. 导出请求</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/transfer/export</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;format&quot;</span><span class="token operator">:</span> <span class="token string">&quot;zip&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;source&quot;</span><span class="token operator">:</span> <span class="token string">&quot;version&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;11111111-1111-4111-8111-111111111111&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;22222222-2222-4222-8222-222222222222&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>source</code> 缺省 <code>editor</code>；显式空值或未知值 400。</li><li><code>format</code> 缺省 <code>zip</code>，只允许 <code>zip</code>/<code>tar.gz</code>。</li><li><code>active</code> 必须传 <code>expected_scope_id</code> 和 <code>expected_snapshot_id</code>，不能传 <code>version</code>；读取时若 active 已变化返回 409 <code>TRANSFER_ACTIVE_CHANGED</code>。</li><li><code>version</code> 必须传范围、<code>expected_scope_id</code>、<code>version</code>、<code>expected_snapshot_id</code>；快照不符返回 409 <code>RELEASE_SNAPSHOT_MISMATCH</code>，版本已删返回 410。</li><li><code>editor</code> 使用 <code>selections</code>；单条选择可省略 <code>environment_key</code>（全环境）、<code>pipeline_key</code>（整渠道）、<code>resource_keys</code>（整渠道配置）。明确选中对象时传 <code>expected_environment_id</code>/<code>expected_scope_id</code>。</li><li>历史无 <code>source</code> 的 editor 请求继续兼容；服务端在请求捕获点解析一次当前身份并固定整次导出。</li></ul><h2 id="_2-导出预览" tabindex="-1"><a class="header-anchor" href="#_2-导出预览">#</a> 2. 导出预览</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/transfer/export-preview</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>请求体与导出相同，不生成包、不改配置。返回：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;OK&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;resolved_source&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;kind&quot;</span><span class="token operator">:</span> <span class="token string">&quot;version&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;captured_at&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2026-10-25T02:00:00Z&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;environment_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;scopes&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">          <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;environment_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">      <span class="token punctuation">]</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;counts&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;configs&quot;</span><span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span> <span class="token property">&quot;assets&quot;</span><span class="token operator">:</span> <span class="token number">4</span><span class="token punctuation">,</span> <span class="token property">&quot;bytes&quot;</span><span class="token operator">:</span> <span class="token string">&quot;12345&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;warnings&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;external_references_not_included:1&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;estimated_bytes&quot;</span><span class="token operator">:</span> <span class="token string">&quot;12345&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>editor 预览不是锁版；预览后编辑区变化，实际导出反映捕获时内容，文件元数据记录实际 <code>captured_at</code>/counts。</p><h2 id="_3-响应" tabindex="-1"><a class="header-anchor" href="#_3-响应">#</a> 3. 响应</h2><p>成功返回 ZIP/GZIP 二进制：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Content-Disposition: attachment; filename=&quot;rainbow-transfer-version-v1.0-&lt;短snapshot&gt;.zip&quot;</span>
<span class="line">Cache-Control: no-store</span>
<span class="line">X-Rainbow-Export-Source: version</span>
<span class="line">X-Rainbow-Snapshot-Id: ...</span>
<span class="line">X-Rainbow-Version: v1.0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>editor 只带 <code>X-Rainbow-Export-Source: editor</code>。错误返回真实 HTTP 状态与 <code>error_type</code>：</p><table><thead><tr><th>HTTP</th><th>error_type</th><th>场景</th></tr></thead><tbody><tr><td>400</td><td><code>TRANSFER_INVALID_REQUEST</code></td><td>混用字段、非法 source/format、缺选择参数</td></tr><tr><td>404</td><td><code>TRANSFER_SELECTION_NOT_FOUND</code> / <code>RELEASE_VERSION_NOT_FOUND</code> / <code>RELEASE_NOT_ACTIVE</code></td><td>配置、版本或生效版本不存在</td></tr><tr><td>409</td><td><code>TRANSFER_ACTIVE_CHANGED</code> / <code>RELEASE_SNAPSHOT_MISMATCH</code></td><td>选择后目标变化</td></tr><tr><td>409/410</td><td><code>SCOPE_IDENTITY_CONFLICT</code> / <code>SCOPE_DELETED</code></td><td>同名范围已替换或删除</td></tr><tr><td>410</td><td><code>RELEASE_VERSION_DELETED</code></td><td>指定版本已删</td></tr><tr><td>413</td><td><code>TRANSFER_EXPORT_LIMIT_EXCEEDED</code></td><td>未压缩输出超过 192 MiB</td></tr><tr><td>503</td><td><code>TRANSFER_RESOURCE_INCOMPLETE</code> / <code>TRANSFER_EXPORT_TIMEOUT</code></td><td>资源缺失或导出超时</td></tr></tbody></table><p>编辑器导出在业务写协调/备份维护保护下捕获；维护中返回既有维护错误。发布来源只读不可变快照，已开始的导出在切版/删除后仍可完成，删除后的新请求拒绝。</p><h2 id="_4-迁移归档格式" tabindex="-1"><a class="header-anchor" href="#_4-迁移归档格式">#</a> 4. 迁移归档格式</h2><p>继续使用 <code>configs.json</code> + <code>files/&lt;file_id&gt;/&lt;file_name&gt;</code>，新增：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;archive_format&quot;</span><span class="token operator">:</span> <span class="token string">&quot;rainbow-transfer-v2&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;export_source&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;kind&quot;</span><span class="token operator">:</span> <span class="token string">&quot;version&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;captured_at&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2026-10-25T02:00:00Z&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;producer&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;app_version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;git_commit&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;scopes&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;environment_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;environments&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipelines&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;business_configs&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;assets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;resources&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span><span class="token property">&quot;file_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;file_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;a.png&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;content_type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;image/png&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;size&quot;</span><span class="token operator">:</span> <span class="token number">12</span><span class="token punctuation">,</span> <span class="token property">&quot;sha256&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;warnings&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>configs.json</code> 的 <code>business_configs</code> 保留 <code>resource_key</code>、<code>alias</code>、<code>name</code>、<code>environment_key</code>、<code>pipeline_key</code>、<code>type</code>、<code>content</code>、<code>remark</code>、<code>is_perm</code>、<code>description</code>；数字使用无损 JSON 解析，不经过 float64。</p><p>版本来源：</p><ul><li>从快照 payload 与发布清单取内容，不从在线编辑区或原始上传目录读取。</li><li><code>release-asset://&lt;asset_id&gt;</code> 按现有标签/JSON/富文本规则改写为 <code>asset://&lt;导出file_id&gt;</code>，保留 query/fragment。</li><li>导出 file_id 由固定 UUID v5 命名空间对 <code>(snapshot_id, asset_id)</code> 生成；同快照重复导出稳定，不同快照不共用身份。</li><li>任何缺清单/缺文件/摘要不符整体失败；外部超链接只保留并写 warning。</li></ul><p>导入：</p><ul><li>迁移包通过 <code>POST /api/v1/transfer/import</code> 的 multipart 字段 <code>archive</code> 上传；目标范围用 <code>environment_key</code>/<code>pipeline_key</code>，并应同时传 <code>expected_environment_id</code>/<code>expected_scope_id</code>。</li><li>v2 正常预览/导入；旧无标识包兼容；未知格式 400；runtime 静态包和整机备份包明确提示类型不符。</li><li>导入到目标 scope 时，资源身份按 <code>(目标 scope_id, 归档 file_id)</code> 做 UUID v5 映射，并重写配置引用；同包重复导入同目标复用同字节资源，不同目标不共用错误归属。</li><li>不导入来源 freeze/head/版本号/active；不复活来源已删除 scope。</li><li>目标是同名重建后的新 scope 时，必须传当前 <code>expected_scope_id</code>；旧 scope 身份返回 410/409，不会把旧包写进新代。</li></ul><h2 id="_5-与其它包的区别" tabindex="-1"><a class="header-anchor" href="#_5-与其它包的区别">#</a> 5. 与其它包的区别</h2>`,26),i(`ul`,null,[l[11]||=n(`<li><strong>迁移归档</strong>：<code>configs.json</code>，可重新导入编辑区。</li><li><strong>runtime 静态包</strong>：<code>config.json</code> + <code>manifest.json</code> + <code>assets/</code>，用于业务部署，不导入编辑区。</li>`,2),i(`li`,null,[l[4]||=i(`strong`,null,`整机业务备份`,-1),l[5]||=e(`：`,-1),l[6]||=i(`code`,null,`manifest.json`,-1),l[7]||=e(` + `,-1),l[8]||=i(`code`,null,`database/business.sqlite`,-1),l[9]||=e(` + 原始资源/快照资源，用于整实例恢复，见 `,-1),a(m,{to:`/api/backup.html`},{default:r(()=>[...l[3]||=[e(`备份 API`,-1)]]),_:1}),l[10]||=e(`。`,-1)])])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};